18	// secretPattern matches high-entropy strings that may be secrets.
19	// Note: / is excluded to prevent matching entire file paths as single tokens.
20	// Base64 and JWT tokens are still caught via high-entropy segments between slashes.
21	var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)
22	
23	// credentialedURIPattern matches URLs that embed userinfo with a password, such
24	// as REDACTED or REDACTED These often have
25	// moderate entropy and are not reliably covered by vendor-specific scanners.
26	var credentialedURIPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9+.-]{1,31}://[^\s/?#@"'` + "`" + `<>:]*:[^\s/?#@"'` + "`" + `<>]+@[^\s"'` + "`" + `<>]+`)
27	
28	var (
29		jdbcPattern            = regexp.MustCompile(`(?i)\bjdbc:[^\s"'<>` + "`" + `]+`)
30		databaseURLPattern     = regexp.MustCompile(`(?i)\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis)://[^\s"'<>` + "`" + `]+`)
31		keywordDSNPattern      = regexp.MustCompile(`(?i)\b[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)(?:\s+[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)){2,}`)
32		semicolonConnPattern   = regexp.MustCompile(`(?i)\b[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|[^=;"'\s]+)(?:;[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|[^=;"'\s]+)){2,}`)
33		credentialValuePattern = regexp.MustCompile(`(?i)(?:^|[^A-Za-z0-9])((?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)[_-]?(?:password|passwd|pwd)|pgpassword|mysql_pwd|redis_password|mongo_password|mongodb_password)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)
34	
35		keywordHostPattern      = regexp.MustCompile(`(?i)(?:^|\s)host=`)
36		keywordUserPattern      = regexp.MustCompile(`(?i)(?:^|\s)user=`)
37		semicolonServerPattern  = regexp.MustCompile(`(?i)(?:^|;)\s*(?:server|data source|datasource|addr|address|network address)\s*=`)
38		semicolonUserPattern    = regexp.MustCompile(`(?i)(?:^|;)\s*(?:user id|userid|user|uid)\s*=`)
39		passwordAssignmentRegex = regexp.MustCompile(`(?i)(?:^|[?&;\s])(?:password|pwd)=("[^"]*"|'[^']*'|[^&;\s"']+)`)
40		credentialJSONKeyRegex  = regexp.MustCompile(`(?i)^(?:(?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)[_-]?(?:password|passwd|pwd)|pgpassword|mysql_pwd|redis_password|mongo_password|mongodb_password)$`)
41		genericPasswordKeyRegex = regexp.MustCompile(`(?i)^(?:password|passwd|pwd)$`)
42	)
43	
44	// entropyThreshold is the minimum Shannon entropy for a string to be considered
45	// a secret. 4.5 was chosen through trial and error: high enough to avoid false
46	// positives on common words and identifiers, low enough to catch typical API keys
47	// and tokens which tend to have entropy well above 5.0.
48	const entropyThreshold = 4.5
49	
50	// RedactedPlaceholder is the replacement text used for redacted secrets.
51	const RedactedPlaceholder = "REDACTED"
52	
53	// redactedPlaceholderForms holds the lowercase variants of RedactedPlaceholder
54	// used to recognize already-redacted values (so we don't double-redact).
55	var redactedPlaceholderForms = func() map[string]struct{} {
56		lower := strings.ToLower(RedactedPlaceholder)
57		return map[string]struct{}{
58			lower:             {},
59			"[" + lower + "]": {},
60			"<" + lower + ">": {},
61		}
62	}()
63	
64	// RedactedBytes represents transcript data that has been through secret
65	// redaction. Consumers that require pre-redacted input (e.g., compact.Compact,
66	// checkpoint stores) accept this type to enforce the contract at compile time.
67	//
68	// Produced by JSONLBytes (primary constructor) or trusted wrappers for data
69	// previously persisted by checkpoint writers.
70	type RedactedBytes struct {
71		data []byte
72	}
73	
74	// Bytes returns the underlying byte slice.
75	func (r RedactedBytes) Bytes() []byte {
76		return r.data
77	}
78	
79	// Len returns the number of bytes in the redacted payload.
80	func (r RedactedBytes) Len() int {
81		return len(r.data)
82	}
83	
84	// AlreadyRedacted wraps transcript bytes known to already be redacted by a
85	// prior write path. Use this ONLY for trusted sources such as persisted
86	// checkpoint transcripts or controlled test fixtures. For fresh transcript
87	// input, use JSONLBytes.
88	func AlreadyRedacted(data []byte) RedactedBytes {
89		return RedactedBytes{data: data}
90	}
