92	var (
93		betterleaksDetector     *detect.Detector
94		betterleaksDetectorOnce sync.Once
95	)
96	
97	func getDetector() *detect.Detector {
98		betterleaksDetectorOnce.Do(func() {
99			d, err := detect.NewDetectorDefaultConfig()
100			if err != nil {
101				return
102			}
103			betterleaksDetector = d
104		})
105		return betterleaksDetector
106	}
107	
108	// region represents a byte range to redact.
109	type region struct{ start, end int }
110	
111	// taggedRegion extends region with a label for typed replacement tokens.
112	// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
113	type taggedRegion struct {
114		region
115	
116		label string
117	}
118	
119	type jsonReplacement struct {
120		key      string
121		original string
122		redacted string
123	}
124	
125	type connectionStringRule struct {
126		pattern   *regexp.Regexp
127		hasSecret func(string) bool
128	}
129	
130	var connectionStringRules = []connectionStringRule{
131		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
132		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
133		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
134		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
135	}
136	
137	// String replaces secrets and PII in s using layered detection:
138	// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
139	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
140	// 3. Credentialed URIs: URLs containing userinfo passwords
141	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
142	// 5. Bounded credential key/value pairs: DB_PASSWORD=...
143	// 6. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
144	// A string is redacted if ANY method flags it.
145	func String(s string) string {
146		var regions []taggedRegion
147	
148		// 1. Entropy-based detection (secrets — always on).
149		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
150			start, end := loc[0], loc[1]
151	
152			// Don't consume characters that are part of JSON/string escape sequences.
153			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
154			// (consuming the 'n' from '\n'), and after replacement the '\' would be
155			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
156			// Only skip for known JSON escape letters to avoid trimming real secrets
157			// that happen to follow a literal backslash in decoded content.
158			if start > 0 && s[start-1] == '\\' {
159				switch s[start] {
160				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
161					start++
162					if end-start < 10 {
163						continue
164					}
165				}
166			}
167	
168			if shannonEntropy(s[start:end]) > entropyThreshold {
169				regions = append(regions, taggedRegion{region: region{start, end}})
170			}
171		}
172	
173		// 2. Pattern-based detection via betterleaks (secrets — always on).
174		if d := getDetector(); d != nil {
175			for _, f := range d.DetectString(s) {
176				if f.Secret == "" {
177					continue
178				}
179				searchFrom := 0
180				for {
181					idx := strings.Index(s[searchFrom:], f.Secret)
182					if idx < 0 {
183						break
184					}
185					absIdx := searchFrom + idx
186					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
187					searchFrom = absIdx + len(f.Secret)
188				}
189			}
190		}
191	
192		// 3. Credentialed URIs (secrets — always on).
193		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
194			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
195		}
196	
197		// 4. Database and connection-string detection (secrets — always on).
198		regions = append(regions, detectConnectionStrings(s)...)
199	
200		// 5. Bounded credential key/value detection (secrets — always on).
201		regions = append(regions, detectCredentialValues(s)...)
202	
203		// 6. PII detection (opt-in — only runs when configured).
204		regions = append(regions, detectPII(getPIIConfig(), s)...)
205	
206		if len(regions) == 0 {
207			return s
208		}
209	
210		// Merge overlapping regions and build result.
211		sort.Slice(regions, func(i, j int) bool {
212			if regions[i].start != regions[j].start {
213				return regions[i].start < regions[j].start
214			}
215			if regions[i].end != regions[j].end {
216				return regions[i].end > regions[j].end // larger region first
217			}
218			return regions[i].label < regions[j].label // deterministic tie-break
219		})
220		merged := []taggedRegion{regions[0]}
221		for _, r := range regions[1:] {
222			last := &merged[len(merged)-1]
223			if r.start <= last.end {
224				if r.end > last.end {
225					last.end = r.end
226				}
227				// Keep the existing label (first/larger region wins)
228			} else {
229				merged = append(merged, r)
230			}
231		}
232	
233		var b strings.Builder
234		prev := 0
235		for _, r := range merged {
236			b.WriteString(s[prev:r.start])
237			b.WriteString(replacementToken(r.label))
238			prev = r.end
239		}
240		b.WriteString(s[prev:])
241		return b.String()
242	}
243	
244	func detectConnectionStrings(s string) []taggedRegion {
245		if !strings.ContainsRune(s, '=') {
246			return nil
247		}
248		var regions []taggedRegion
249		for _, rule := range connectionStringRules {
250			regions = append(regions, detectConnectionStringRule(s, rule)...)
251		}
252		return regions
253	}
254	
255	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
256		var regions []taggedRegion
257		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
258			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
259			if start >= end {
260				continue
261			}
262			if rule.hasSecret(s[start:end]) {
263				regions = append(regions, taggedRegion{region: region{start, end}})
264			}
265		}
266		return regions
267	}
268	
269	func trimConnectionStringEnd(s string, start, end int) int {
270		for end > start {
271			switch s[end-1] {
272			case '.', ',', ';', ':', '!', '?', ')', ']':
273				end--
274			default:
275				return end
276			}
277		}
278		return end
279	}
280	
281	func hasJDBCPassword(candidate string) bool {
282		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
283			return false
284		}
285		return hasNonPlaceholderPasswordAssignment(candidate)
286	}
287	
288	func hasDatabaseURLSecret(candidate string) bool {
289		u, err := url.Parse(candidate)
290		if err != nil || u.Scheme == "" || u.Host == "" {
291			return false
292		}
293		for key, values := range u.Query() {
294			if !isPasswordQueryKey(key) {
295				continue
296			}
297			for _, value := range values {
298				if hasNonPlaceholderPasswordValue(value) {
299					return true
300				}
301			}
302		}
303		return false
304	}
305	
306	func isPasswordQueryKey(key string) bool {
307		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
308	}
309	
310	func hasKeywordDSNPassword(candidate string) bool {
311		return keywordHostPattern.MatchString(candidate) &&
312			keywordUserPattern.MatchString(candidate) &&
313			hasNonPlaceholderPasswordAssignment(candidate)
314	}
315	
316	func hasSemicolonConnectionPassword(candidate string) bool {
317		return semicolonServerPattern.MatchString(candidate) &&
318			semicolonUserPattern.MatchString(candidate) &&
319			hasNonPlaceholderPasswordAssignment(candidate)
320	}
321	
322	func detectCredentialValues(s string) []taggedRegion {
323		var regions []taggedRegion
324		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
325			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
326				continue
327			}
328			start, end := unquoteRange(s, loc[4], loc[5])
329			if hasNonPlaceholderPasswordValue(s[start:end]) {
330				regions = append(regions, taggedRegion{region: region{start, end}})
331			}
332		}
333		return regions
334	}
335	
336	func unquoteRange(s string, start, end int) (int, int) {
337		if end-start < 2 {
338			return start, end
339		}
340		first, last := s[start], s[end-1]
341		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
342			return start + 1, end - 1
343		}
344		return start, end
345	}
346	
347	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
348		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
349			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
350				start, end := unquoteRange(candidate, loc[2], loc[3])
351				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
352					return true
353				}
354			}
355		}
356		return false
357	}
358	
359	func hasNonPlaceholderPasswordValue(value string) bool {
360		return value != "" && !isPlaceholderSecretValue(value)
361	}
362	
363	func isPlaceholderSecretValue(value string) bool {
364		normalized := strings.ToLower(strings.TrimSpace(value))
365		normalized = strings.Trim(normalized, `"'`)
366		if normalized == "" {
367			return true
368		}
369		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
370			return true
371		}
372		if _, ok := redactedPlaceholderForms[normalized]; ok {
373			return true
374		}
375		switch normalized {
376		case "xxx", "xxxx", "changeme", "example":
377			return true
378		default:
379			return false
380		}
381	}
382	
383	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
384		normalized := normalizeCredentialJSONKey(key)
385		if credentialJSONKeyRegex.MatchString(normalized) {
386			return true
387		}
388		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
389	}
390	
391	func isCredentialJSONObject(obj map[string]any) bool {
392		var hasHost, hasUser bool
393		for key := range obj {
394			switch normalizeCredentialJSONKey(key) {
395			case "host", "hostname", "server", "addr", "address", "datasource", "data_source":
396				hasHost = true
397			case "user", "username", "userid", "user_id", "uid":
398				hasUser = true
399			}
400			if hasHost && hasUser {
401				return true
402			}
403		}
404		return false
405	}
406	
407	func normalizeCredentialJSONKey(key string) string {
408		key = strings.ToLower(strings.TrimSpace(key))
409		key = strings.ReplaceAll(key, "-", "_")
410		key = strings.ReplaceAll(key, " ", "_")
411		return key
412	}
413	
414	// Bytes is a convenience wrapper around String for []byte content.
415	func Bytes(b []byte) []byte {
416		s := string(b)
417		redacted := String(s)
418		if redacted == s {
419			return b
420		}
421		return []byte(redacted)
422	}
423	
424	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
425	// the result as RedactedBytes, certifying the output has been through redaction.
426	func JSONLBytes(b []byte) (RedactedBytes, error) {
427		s := string(b)
428		redacted, err := JSONLContent(s)
429		if err != nil {
430			return RedactedBytes{}, err
431		}
432		if redacted == s {
433			return RedactedBytes{data: b}, nil
434		}
435		return RedactedBytes{data: []byte(redacted)}, nil
436	}
437	
438	// JSONLContent parses each line as JSON to determine which string values
439	// need redaction, then performs targeted replacements on the raw JSON bytes.
440	// Lines with no secrets are returned unchanged, preserving original formatting.
441	//
442	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
443	// OpenCode export), the function first attempts to parse the entire content as
444	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
445	// is used instead of falling back to entropy-based detection on raw text lines,
446	// which would corrupt high-entropy identifiers.
447	func JSONLContent(content string) (string, error) {
448		// Try parsing the entire content as a single JSON value first.
449		// Uses a streaming decoder to avoid copying the full content into []byte.
450		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
451		// the content is JSONL (multiple values) and we fall through to line-by-line.
452		trimmed := strings.TrimSpace(content)
453		if len(trimmed) > 0 {
454			dec := json.NewDecoder(strings.NewReader(trimmed))
455			var parsed any
456			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
457				// Content is a single JSON value (object/array) — redact field-aware.
458				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed))
459				if err != nil {
460					return "", err
461				}
462				return result, nil
463			}
464		}
465	
466		// Fall back to line-by-line JSONL processing.
467		lines := strings.Split(content, "\n")
468		var b strings.Builder
469		for i, line := range lines {
470			if i > 0 {
471				b.WriteByte('\n')
472			}
473			lineTrimmed := strings.TrimSpace(line)
474			if lineTrimmed == "" {
475				b.WriteString(line)
476				continue
477			}
478			var parsed any
479			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
480				b.WriteString(String(line))
481				continue
482			}
483			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed))
484			if err != nil {
485				return "", err
486			}
487			b.WriteString(result)
488		}
489		return b.String(), nil
490	}
491	
492	// applyJSONReplacements applies collected (original, redacted) string pairs
493	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
494	// Returns s unchanged if repls is empty.
495	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
496		if len(repls) == 0 {
497			return s, nil
498		}
499		for _, r := range repls {
500			origJSON, err := jsonEncodeString(r.original)
501			if err != nil {
502				return "", err
503			}
504			replJSON, err := jsonEncodeString(r.redacted)
505			if err != nil {
506				return "", err
507			}
508			if r.key == "" {
509				s = strings.ReplaceAll(s, origJSON, replJSON)
510				continue
511			}
512			keyJSON, err := jsonEncodeString(r.key)
513			if err != nil {
514				return "", err
515			}
516			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
517		}
518		return s, nil
519	}
520	
521	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
522	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
523	// substitution to value positions so a key's own redacted text is not
524	// rewritten when it collides with another field's value.
525	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
526		if !strings.Contains(s, keyJSON) {
527			return s
528		}
529		var b strings.Builder
530		b.Grow(len(s))
531		i := 0
532		for i < len(s) {
533			j := strings.Index(s[i:], keyJSON)
534			if j < 0 {
535				b.WriteString(s[i:])
536				break
537			}
538			keyEnd := i + j + len(keyJSON)
539			b.WriteString(s[i : i+j])
540			b.WriteString(keyJSON)
541			p := keyEnd
542			for p < len(s) && isJSONWhitespace(s[p]) {
543				p++
544			}
545			if p >= len(s) || s[p] != ':' {
546				i = keyEnd
547				continue
548			}
549			p++
550			for p < len(s) && isJSONWhitespace(s[p]) {
551				p++
552			}
553			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
554				b.WriteString(s[keyEnd:p])
555				b.WriteString(replJSON)
556				i = p + len(origJSON)
557				continue
558			}
559			i = keyEnd
560		}
561		return b.String()
562	}
563	
564	func isJSONWhitespace(c byte) bool {
565		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
566	}
567	
568	// isSingleJSONValue returns true if the decoder has reached EOF (no more
569	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
570	// object) from JSONL (multiple concatenated values). We attempt a second Decode
571	// and require io.EOF rather than relying on dec.More(), which is documented for
572	// use inside arrays/objects and not for top-level value boundaries.
573	func isSingleJSONValue(dec *json.Decoder) bool {
574		var discard json.RawMessage
575		return dec.Decode(&discard) == io.EOF
576	}
577	
578	// collectJSONLReplacements walks a parsed JSON value and collects unique string
579	// replacements for values that need redaction.
580	func collectJSONLReplacements(v any) []jsonReplacement {
581		seen := make(map[string]bool)
582		var repls []jsonReplacement
583		var walk func(key string, credentialContext bool, v any)
584		walk = func(key string, credentialContext bool, v any) {
585			switch val := v.(type) {
586			case map[string]any:
587				if shouldSkipJSONLObject(val) {
588					return
589				}
590				childCredentialContext := credentialContext || isCredentialJSONObject(val)
591				for k, child := range val {
592					if shouldSkipJSONLField(k) {
593						continue
594					}
595					walk(k, childCredentialContext, child)
596				}
597			case []any:
598				for _, child := range val {
599					walk("", credentialContext, child)
600				}
601			case string:
602				redacted := String(val)
603				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
604					redacted = RedactedPlaceholder
605				}
606				if redacted != val {
607					seenKey := key + "\x00" + val
608					if !seen[seenKey] {
609						seen[seenKey] = true
610						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
611					}
612				}
613			}
614		}
615		walk("", false, v)
616		return repls
617	}
618	
619	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
620	// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
621	func shouldSkipJSONLField(key string) bool {
622		if key == "signature" {
623			return true
624		}
625		lower := strings.ToLower(key)
626	
627		// Skip ID fields
628		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
629			return true
630		}
631	
632		// Skip common path and directory fields from agent transcripts.
633		// These appear frequently in tool calls and are structural, not secrets.
634		switch lower {
635		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
636			return true
637		}
638	
639		return false
640	}
641	
642	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
643	func shouldSkipJSONLObject(obj map[string]any) bool {
644		t, ok := obj["type"].(string)
645		return ok && (strings.HasPrefix(t, "image") || t == "base64")
646	}
647	
648	func shannonEntropy(s string) float64 {
649		if len(s) == 0 {
650			return 0
651		}
652		freq := make(map[byte]int)
653		for i := range len(s) {
654			freq[s[i]]++
655		}
656		length := float64(len(s))
657		var entropy float64
658		for _, count := range freq {
659			p := float64(count) / length
660			entropy -= p * math.Log2(p)
661		}
662		return entropy
663	}
664	
665	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
666	func jsonEncodeString(s string) (string, error) {
667		var buf bytes.Buffer
668		enc := json.NewEncoder(&buf)
669		enc.SetEscapeHTML(false)
670		if err := enc.Encode(s); err != nil {
671			return "", fmt.Errorf("json encode string: %w", err)
672		}
673		return strings.TrimSuffix(buf.String(), "\n"), nil
674	}
