117	// Validate returns an error if the settings combination is semantically invalid.
118	// A model without a provider is meaningless: the model hint needs a provider to
119	// route to. The load path calls Validate() after merging, catching hand-edited
120	// files that land in this state.
121	func (s *SummaryGenerationSettings) Validate() error {
122		if s == nil {
123			return nil
124		}
125		if s.Model != "" && s.Provider == "" {
126			return fmt.Errorf("summary_generation.model %q set without summary_generation.provider", s.Model)
127		}
128		return nil
129	}
