495	// mergeRedaction merges redaction overrides into existing RedactionSettings.
496	// Only fields present in the override JSON are applied.
497	func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
498		var raw map[string]json.RawMessage
499		if err := json.Unmarshal(data, &raw); err != nil {
500			return fmt.Errorf("parsing redaction: %w", err)
501		}
502		if piiRaw, ok := raw["pii"]; ok {
503			if dst.PII == nil {
504				dst.PII = &PIISettings{}
505			}
506			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
507				return err
508			}
509		}
510		return nil
511	}
