759	func parseCheckpointsVersion(val any) (int, bool) {
760		v, ok := val.(int)
761		if ok && (v == 1 || v == 2) {
762			return v, true
763		}
764		floatV, ok := val.(float64)
765		if ok && (floatV == 1 || floatV == 2) {
766			return int(floatV), true
767		}
768		stringV, ok := val.(string)
769		if ok {
770			parsed, err := strconv.Atoi(stringV)
771			if err == nil && (parsed == 1 || parsed == 2) {
772				return parsed, true
773			}
774		}
775		return 1, false
776	}
